// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 newVal) public {
        // keep away from the initial value so a change is observable
        vm.assume(newVal != 1 ether);

        // freeze the configuration: after Initialized(), SetMinSum must revert
        c.Initialized();

        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }

        // General rule: a reverted SetMinSum must leave MinSum unchanged
        // (i.e. a revert must never coexist with MinSum == newVal).
        // Reference: reverts and MinSum stays 1 ether -> holds.
        // Mutant: assigns MinSum = newVal before reverting -> broken.
        assertTrue(!(ok == false && c.MinSum() == newVal));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 newVal, bool doInit) public {
        newVal = bound(newVal, 0, type(uint256).max);

        if (doInit) {
            c.Initialized();
        }

        uint256 before = c.MinSum();
        address actor = address(0xA11CE);

        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterVal = c.MinSum();

        // General rule: a SetMinSum call on an initialized contract reverts and
        // must leave MinSum exactly as it was; on an uninitialized contract it
        // succeeds and must set MinSum to the requested value. The mutant writes
        // MinSum before the check, so a reverted call in the mutant changes MinSum.
        assertTrue(
            (ok && !doInit && afterVal == newVal) ||
            (!ok && doInit && afterVal == before)
        );
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 v, bool doInit) public {
        v = bound(v, 0, type(uint256).max);
        address actor = address(0xA11ce);
        // First, set a known baseline value while not yet initialized.
        vm.prank(actor);
        c.SetMinSum(v + 1);
        uint256 baseline = c.MinSum();
        if (doInit) {
            vm.prank(actor);
            c.Initialized();
        }
        bool ok;
        vm.prank(actor);
        try c.SetMinSum(v) { ok = true; } catch { ok = false; }
        // Rule: the call succeeds iff not initialized; MinSum becomes v only on success,
        // otherwise it keeps the baseline value. The mutant writes MinSum even when reverting.
        assertTrue((ok && !doInit && c.MinSum() == v) || (!ok && doInit && c.MinSum() == baseline));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val) public {
        // Admissible domain: any value; only exclude the value equal to the
        // initial MinSum, where mutant and reference happen to coincide.
        vm.assume(val != 1 ether);

        uint256 before = c.MinSum();

        // Initialize: from now on SetMinSum must always revert and have no effect.
        c.Initialized();

        bool ok;
        try c.SetMinSum(val) { ok = true; } catch { ok = false; }

        // Rule: an already-initialized contract reverts SetMinSum and MinSum
        // is unchanged (still the value it had before the call).
        assertTrue(!ok && c.MinSum() == before);
    }
}

