pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 v, bool doInit) public {
        // keep the whole uint256 domain admissible; no narrowing assumptions
        if (doInit) {
            // initialize the contract so that every later SetMinSum must revert
            c.Initialized();
        }
        uint256 before = c.MinSum();
        bool ok;
        try c.SetMinSum(v) { ok = true; } catch { ok = false; }
        uint256 after_ = c.MinSum();
        // General rule: SetMinSum(v) succeeds exactly when the contract is not
        // initialized, and then (and only then) MinSum becomes v; a reverting
        // call must leave MinSum untouched.
        assertTrue(ok ? (after_ == v && !doInit) : (after_ == before));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val) public {
        c.Initialized();
        c.SetMinSum(val);
        assertTrue(c.MinSum() != val, "initialized contract must ignore SetMinSum");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _val) public {
        // before initialization, SetMinSum must succeed
        c.SetMinSum(_val);
        assert(c.MinSum() == _val);
    }
}
